typedef float rational_t;
typedef float time_value_t;

enum widget_dir_e {
  WDIR_Left,
  WDIR_Right,
  WDIR_Up,
  WDIR_Down
};

struct virtual_entry {
  short adjustment;
  short padding;
  void (*function)();
};

class bitmap_widget {
  char padding[0x140];
  virtual_entry *table;
public:
  void set_subrect(int x0, int y0, int x1, int y1) {
    virtual_entry *call = (virtual_entry *)((char *)table + 0xD8);
    ((void (*)(void *, int, int, int, int))call->function)
      ((char *)this + call->adjustment, x0, y0, x1, y1);
  }
  void move_to(short x, short y) {
    virtual_entry *call = (virtual_entry *)((char *)table + 0x68);
    ((void (*)(void *, short, short))call->function)
      ((char *)this + call->adjustment, x, y);
  }
};

class fluid_bar {
  char padding0[0x14];
  unsigned int flags;
  char padding1[0x12C];
  widget_dir_e dir;
  char padding2[0xC];
  bitmap_widget *bar_map;
  char name[8];
  rational_t w, h;
  rational_t full_val, to_val, cur_val, fill_rate, empty_rate, special_rate;
  rational_t old_full_val, old_to_val, old_cur_val, old_fill_rate, old_empty_rate;
  bool update, using_special_rate;
public:
  bool is_shown() const { return flags & 1; }
  void frame_advance(time_value_t time_inc);
};

#define assert(exp) ((void)0)

void fluid_bar::frame_advance( time_value_t time_inc )
{
  if ( !is_shown() ) return;

  assert( full_val >= 0.0f );
  assert( to_val >= 0.0f && to_val <= full_val );
  assert( cur_val >= 0.0f && cur_val <= full_val );

  if ( update || cur_val != to_val )
  {
    if ( cur_val < to_val )
    {
      if ( using_special_rate )
      {
        cur_val += time_inc * full_val * special_rate;
      }
      else
      {
        cur_val += time_inc * full_val * fill_rate;
      }

      if ( cur_val > to_val )
      {
        cur_val = to_val;
      }
    }
    else
    {
      if ( using_special_rate )
      {
        cur_val -= time_inc * full_val * special_rate;
      }
      else
      {
        cur_val -= time_inc * full_val * empty_rate;
      }

      if ( cur_val < to_val )
      {
        cur_val = to_val;
      }
    }

    int adj_w = int( w * ( cur_val / full_val ) + 0.5f );
    int adj_h = int( h * ( cur_val / full_val ) + 0.5f );

    int x0 = 0, y0 = 0, x1 = int( w ), y1 = int( h );

    if ( dir == WDIR_Left )
    {
      x0 = int( w ) - adj_w;
    }
    else if ( dir == WDIR_Right )
    {
      x1 = adj_w;
    }
    else if ( dir == WDIR_Up )
    {
      y0 = int( h ) - adj_h;
    }
    else if ( dir == WDIR_Down )
    {
      y1 = adj_h;
    }

    bar_map->set_subrect( x0, y0, x1, y1 );
    bar_map->move_to( x0, y0 );

    update = false;
    old_full_val = full_val;
    old_to_val = to_val;
    old_cur_val = cur_val;
    old_fill_rate = fill_rate;
    old_empty_rate = empty_rate;

    if ( cur_val == to_val )
    {
      using_special_rate = false;
    }
  }
}
